import { useState } from "react";
import type { ReactNode } from "react";
import { Modal, Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface HoverCardProps {
  children: ReactNode;
  content: ReactNode;
  /** Extend the inner, named parts of the card: overlay or card. The React Native counterpart of `classNames`. */
  styles?: {
    overlay?: StyleProp<ViewStyle>;
    card?: StyleProp<ViewStyle>;
  };
}

/** There is no hover on a phone, so a press on the trigger opens the card as a small floating panel. */
export function HoverCard({ children, content, styles: parts }: HoverCardProps) {
  const tokens = useTokens();
  const [open, setOpen] = useState(false);

  return (
    <>
      <Pressable accessibilityRole="button" accessibilityState={{ expanded: open }} onPress={() => setOpen(true)} style={{ alignSelf: "flex-start" }}>
        {children}
      </Pressable>
      <Modal transparent animationType="fade" visible={open} onRequestClose={() => setOpen(false)} statusBarTranslucent>
        <Pressable accessibilityLabel="Close" onPress={() => setOpen(false)} style={[local.overlay, parts?.overlay]}>
          <Pressable onPress={() => undefined} style={[local.card, { borderColor: tokens.border, backgroundColor: tokens.surface }, parts?.card]}>
            {content}
          </Pressable>
        </Pressable>
      </Modal>
    </>
  );
}

export interface HoverCardProfileProps {
  name: string;
  role?: string;
  bio?: string;
  stats?: { label: string; value: string }[];
  meta?: string;
}

/** A ready-made profile body for the card. */
export function HoverCardProfile({ name, role, bio, stats = [], meta }: HoverCardProfileProps) {
  const tokens = useTokens();

  return (
    <View style={{ gap: metrics.space[2] }}>
      <Text style={{ color: tokens.foreground, fontSize: metrics.text.sm, fontWeight: "600" }}>{name}</Text>
      {role ? <Text style={{ color: tokens.textSecondary, fontSize: metrics.text.xs }}>{role}</Text> : null}
      {bio ? <Text style={{ color: tokens.textSecondary, fontSize: metrics.text.sm }}>{bio}</Text> : null}
      {stats.length ? (
        <View style={{ flexDirection: "row", gap: metrics.space[4] }}>
          {stats.map((stat) => (
            <Text key={stat.label} style={{ color: tokens.textMuted, fontSize: metrics.text.xs }}>
              <Text style={{ color: tokens.foreground, fontWeight: "600" }}>{stat.value}</Text> {stat.label}
            </Text>
          ))}
        </View>
      ) : null}
      {meta ? <Text style={{ color: tokens.textMuted, fontSize: metrics.text.xs }}>{meta}</Text> : null}
    </View>
  );
}

const local = StyleSheet.create({
  overlay: { flex: 1, alignItems: "center", justifyContent: "center", padding: metrics.space[5], backgroundColor: "rgba(10, 10, 10, 0.3)" },
  card: { width: "100%", maxWidth: 320, borderWidth: 1, borderRadius: 26, padding: metrics.space[4] },
});

export default HoverCard;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
